  def icon(name, **attrs)
    path = ICONS.fetch(name.to_s)
    css = attrs.delete(:class) || "size-4"
    hidden = attrs.key?(:"aria-label") ? nil : "true"
    tag.svg(viewBox: "0 0 24 24", fill: "currentColor", xmlns: "http://www.w3.org/2000/svg",
            class: css, "aria-hidden": hidden, **attrs) do
      tag.path(d: path)
    end
  end
